1	import { NextResponse } from "next/server";
2	import { createAdminClient } from "@/lib/supabase/admin";
3	import { checkPermissionAccess } from "@/lib/permissions-server";
4	import { computeOptionCosts } from "@/lib/cost-items/compute";
5	
6	// Issue #125 Phase 4: option-level `cost` and per-choice `cost` derive from
7	// linked cost_items at read time (computeOptionCosts). The admin UI no
8	// longer writes these fields, but any legacy client that still sends them
9	// must be ignored so stored values can't drift further. Phase 5 drops the
10	// columns entirely.
11	function stripCostFromChoices(choices: unknown): unknown {
12	  if (!Array.isArray(choices)) return choices;
13	  return choices.map((c) => {
14	    if (!c || typeof c !== "object") return c;
15	    const { cost: _cost, ...rest } = c as Record<string, unknown>;
16	    void _cost;
17	    return rest;
18	  });
19	}
