21	export async function GET(request: Request) {
22	  const admin = await checkPermissionAccess("manage_finances");
23	  if (!admin) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
24	
25	  const { searchParams } = new URL(request.url);
26	  const tripId = searchParams.get("trip_id");
27	  if (!tripId) return NextResponse.json({ error: "trip_id is required" }, { status: 400 });
28	
29	  const adminClient = createAdminClient();
30	  const { data, error } = await adminClient
31	    .from("trip_options")
32	    .select("*, option_groups(id, name, sort_order)")
33	    .eq("trip_id", tripId)
34	    .order("sort_order", { referencedTable: "option_groups" })
35	    .order("sort_order");
36	
37	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
38	  // Replace stored option costs with values computed from linked cost_items.
39	  const options = await computeOptionCosts(adminClient, data || []);
40	  return NextResponse.json({ options });
41	}
