43	export async function POST(request: Request) {
44	  const admin = await checkPermissionAccess("manage_finances");
45	  if (!admin) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
46	
47	  const { group_id, trip_id, name, description, option_type, choices, cost, is_required, icon, linked_contest_id, depends_on_option_id, sort_order, max_total } = await request.json();
48	  if (!group_id || !trip_id || !name || !option_type) {
49	    return NextResponse.json({ error: "group_id, trip_id, name, and option_type are required" }, { status: 400 });
50	  }
51	  if (cost !== undefined && cost !== null) {
52	    console.warn(`[POST /api/admin/options] Ignoring legacy 'cost' field for ${name} — costs derive from cost_items (issue #125 Phase 4).`);
53	  }
54	
55	  const adminClient = createAdminClient();
56	
57	  // Auto sort_order within group if not provided
58	  let order = sort_order;
59	  if (order === undefined) {
60	    const { data: existing } = await adminClient
61	      .from("trip_options")
62	      .select("sort_order")
63	      .eq("group_id", group_id)
64	      .order("sort_order", { ascending: false })
65	      .limit(1);
66	    order = (existing?.[0]?.sort_order ?? -1) + 1;
67	  }
68	
69	  const insert: Record<string, unknown> = { group_id, trip_id, name, option_type, sort_order: order };
70	  if (description !== undefined) insert.description = description;
71	  if (choices !== undefined) insert.choices = stripCostFromChoices(choices);
72	  if (is_required !== undefined) insert.is_required = is_required;
73	  if (icon !== undefined) insert.icon = icon;
74	  if (linked_contest_id !== undefined) insert.linked_contest_id = linked_contest_id;
75	  if (depends_on_option_id !== undefined) insert.depends_on_option_id = depends_on_option_id;
76	  if (max_total !== undefined) insert.max_total = max_total;
77	
78	  const { data, error } = await adminClient
79	    .from("trip_options")
80	    .insert(insert)
81	    .select()
82	    .single();
83	
84	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
85	  return NextResponse.json({ option: data });
86	}
