88	export async function PUT(request: Request) {
89	  const admin = await checkPermissionAccess("manage_finances");
90	  if (!admin) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
91	
92	  const { id, name, description, option_type, choices, cost, is_required, icon, linked_contest_id, depends_on_option_id, sort_order, max_total } = await request.json();
93	  if (!id) return NextResponse.json({ error: "id is required" }, { status: 400 });
94	  if (cost !== undefined && cost !== null) {
95	    console.warn(`[PUT /api/admin/options] Ignoring legacy 'cost' field for option ${id} — costs derive from cost_items (issue #125 Phase 4).`);
96	  }
97	
98	  const adminClient = createAdminClient();
99	  const updates: Record<string, unknown> = {};
100	  if (name !== undefined) updates.name = name;
101	  if (description !== undefined) updates.description = description;
102	  if (option_type !== undefined) updates.option_type = option_type;
103	  if (choices !== undefined) updates.choices = stripCostFromChoices(choices);
104	  if (is_required !== undefined) updates.is_required = is_required;
105	  if (icon !== undefined) updates.icon = icon;
106	  if (linked_contest_id !== undefined) updates.linked_contest_id = linked_contest_id;
107	  if (depends_on_option_id !== undefined) updates.depends_on_option_id = depends_on_option_id;
108	  if (sort_order !== undefined) updates.sort_order = sort_order;
109	  if (max_total !== undefined) updates.max_total = max_total;
110	
111	  const { error } = await adminClient
112	    .from("trip_options")
113	    .update(updates)
114	    .eq("id", id);
115	
116	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
117	  return NextResponse.json({ success: true });
118	}
