120	export async function DELETE(request: Request) {
121	  const admin = await checkPermissionAccess("manage_finances");
122	  if (!admin) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
123	
124	  const { id } = await request.json();
125	  if (!id) return NextResponse.json({ error: "id is required" }, { status: 400 });
126	
127	  const adminClient = createAdminClient();
128	
129	  // Clean up financial_transactions linked to this option first
130	  // (option_id FK is ON DELETE CASCADE, but be explicit for clarity)
131	  const { error: txError } = await adminClient
132	    .from("financial_transactions")
133	    .delete()
134	    .eq("option_id", id)
135	    .eq("source", "option");
136	
137	  if (txError) return NextResponse.json({ error: txError.message }, { status: 500 });
138	
139	  // Delete the option (cascades to user_option_selections via FK)
140	  const { error: deleteError } = await adminClient
141	    .from("trip_options")
142	    .delete()
143	    .eq("id", id);
144	
145	  if (deleteError) return NextResponse.json({ error: deleteError.message }, { status: 500 });
146	
147	  return NextResponse.json({ success: true });
148	}
