11	export default function OptionsAdminPage() {
12	  const params = useParams();
13	  const tripId = params.tripId as string;
14	  const router = useRouter();
15	  const [allowed, setAllowed] = useState<boolean | null>(null);
16	  const [tab, setTab] = useState<"builder" | "selections" | "summary">("builder");
17	  const [selectionExporter, setSelectionExporter] = useState<(() => void) | null>(null);
18	  const handleExportReady = useCallback((exporter: (() => void) | null) => {
19	    setSelectionExporter(() => exporter);
20	  }, []);
21	
22	  useEffect(() => {
