51	
52	      <div className="flex items-center justify-between gap-3">
53	        <h1 className="text-2xl font-bold text-gray-900">Trip Options</h1>
54	        {tab !== "builder" && (
55	          <button
56	            onClick={() => selectionExporter?.()}
57	            disabled={!selectionExporter}
58	            className="flex items-center gap-1.5 px-3 py-2 bg-emerald-600 text-white text-sm font-semibold rounded-xl shadow-sm active:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed"
59	            title="Download current selections as an Excel file"
60	          >
61	            <svg
62	              className="w-4 h-4"
63	              fill="none"
64	              stroke="currentColor"
65	              viewBox="0 0 24 24"
66	            >
67	              <path
68	                strokeLinecap="round"
69	                strokeLinejoin="round"
70	                strokeWidth={2}
71	                d="M4 16v2a2 2 0 002 2h12a2 2 0 002-2v-2M7 10l5 5m0 0l5-5m-5 5V4"
72	              />
73	            </svg>
74	            Excel
75	          </button>
76	        )}
77	      </div>
78	
79	      {/* Tab switcher */}
80	      <div className="flex gap-1 bg-gray-100 rounded-xl p-1">
81	        <button
82	          onClick={() => setTab("builder")}
83	          className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-colors ${
