94	            tab === "selections"
95	              ? "bg-white text-gray-900 shadow-sm"
96	              : "text-gray-500"
97	          }`}
98	        >
99	          Selections
100	        </button>
101	        <button
102	          onClick={() => setTab("summary")}
103	          className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-colors ${
104	            tab === "summary"
105	              ? "bg-white text-gray-900 shadow-sm"
106	              : "text-gray-500"
107	          }`}
108	        >
109	          Summary
110	        </button>
111	      </div>
112	
113	      {tab === "builder" && <OptionBuilder tripId={tripId} />}
114	      {tab === "selections" && (
115	        <SelectionDashboard tripId={tripId} onExportReady={handleExportReady} />
