3	import { useEffect, useState, useMemo, useCallback } from "react";
4	import {
5	  CATEGORY_LABELS,
6	  UNCATEGORIZED_KEY,
7	  UNCATEGORIZED_LABEL,
8	  groupByCategory,
9	  compareCostItems,
10	} from "@/lib/cost-items/categories";
11	import { DragHandle } from "@/components/DragHandle";
12	
13	interface CostItem {
14	  id: string;
15	  name: string;
16	  cost: number;
17	  category: string | null;
18	  sort_order: number;
19	  linked_option_id: string | null;
20	  linked_choices: string[]; // populated by the loader
21	  included_in_trip_cost: boolean;
22	}
23	
24	interface OptionChoice {
25	  label?: string;
26	  value: string;
27	  cost?: number | null;
28	}
29	
30	interface OptionInput {
31	  id: string;
32	  name: string;
33	  option_type: string;
34	  cost?: number | null;
35	  choices?: OptionChoice[] | null;
36	}
