45	export function CostItemLinksModal({
46	  option,
47	  tripId,
48	  onClose,
49	  onSaved,
50	}: {
51	  option: OptionInput;
52	  tripId: string;
53	  onClose: () => void;
54	  onSaved?: () => void;
55	}) {
56	  const [allItems, setAllItems] = useState<CostItem[]>([]);
57	  const [loading, setLoading] = useState(true);
58	  const [errorMsg, setErrorMsg] = useState<string | null>(null);
59	  const [saving, setSaving] = useState(false);
60	
61	  // Working copy: the link state admin is editing (uncommitted until Save).
62	  // Map<costItemId, { linkedHere: boolean; choices: Set<choice_value> }>
63	  const [draft, setDraft] = useState<Map<string, { linkedHere: boolean; choices: Set<string> }>>(
64	    new Map(),
65	  );
66	
67	  const isCheckbox = option.option_type === "checkbox";
68	  const choices = useMemo(
69	    () => (Array.isArray(option.choices) ? option.choices : []),
70	    [option.choices],
71	  );
72	
73	  const load = useCallback(async () => {
74	    setLoading(true);
75	    const r = await fetch(`/api/admin/financials/cost-items?trip_id=${tripId}`);
76	    const data = await r.json();
77	
78	    // Junction rows for ALL items (we need to know all choices each item already triggers).
79	    const itemIds = (data.items || []).map((i: { id: string }) => i.id);
80	    const choiceRowsByItem = new Map<string, string[]>();
81	    if (itemIds.length > 0) {
82	      const j = await fetch(`/api/admin/financials/cost-items/links?trip_id=${tripId}`);
83	      if (j.ok) {
84	        const jd = await j.json();
85	        for (const row of jd.junction || []) {
86	          if (!choiceRowsByItem.has(row.cost_item_id)) {
87	            choiceRowsByItem.set(row.cost_item_id, []);
88	          }
89	          choiceRowsByItem.get(row.cost_item_id)!.push(row.choice_value);
90	        }
91	      }
92	    }
93	
94	    // Cost items flagged `included_in_trip_cost` flow into the Trip Cost
95	    // option (option_type='trip_cost') automatically. Linking them to a
96	    // regular option would double-count them — hide from this picker.
97	    const items: CostItem[] = (data.items || [])
98	      .filter((i: CostItem) => !i.included_in_trip_cost)
99	      .map((i: CostItem) => ({
100	        ...i,
101	        linked_choices: choiceRowsByItem.get(i.id) || [],
102	      }));
103	    setAllItems(items);
104	
105	    // Initialize draft from current state, scoped to THIS option.
106	    const initial = new Map<string, { linkedHere: boolean; choices: Set<string> }>();
107	    for (const it of items) {
108	      initial.set(it.id, {
109	        linkedHere: it.linked_option_id === option.id,
110	        choices: new Set(it.linked_option_id === option.id ? it.linked_choices : []),
111	      });
112	    }
113	    setDraft(initial);
114	    setLoading(false);
115	  }, [tripId, option.id]);
116	
117	  useEffect(() => { load(); }, [load]);
118	
119	  // Items grouped by their category, sorted within each group by sort_order
120	  // (admin's manual order on the cost-items page). Items linked elsewhere
121	  // stay visible but greyed.
122	  const groupedVisibleItems = useMemo(() => {
123	    const sorted = allItems.slice().sort(compareCostItems);
124	    return groupByCategory(sorted);
125	  }, [allItems]);
126	
127	  function toggleLinkedHere(itemId: string, checked: boolean) {
128	    setDraft((prev) => {
129	      const next = new Map(prev);
130	      const cur = next.get(itemId) || { linkedHere: false, choices: new Set<string>() };
131	      next.set(itemId, {
132	        linkedHere: checked,
133	        choices: checked ? cur.choices : new Set(),
134	      });
135	      return next;
136	    });
137	  }
138	
139	  function toggleChoice(itemId: string, choiceValue: string, checked: boolean) {
140	    setDraft((prev) => {
141	      const next = new Map(prev);
142	      const cur = next.get(itemId) || { linkedHere: false, choices: new Set<string>() };
143	      const newChoices = new Set(cur.choices);
144	      if (checked) newChoices.add(choiceValue);
145	      else newChoices.delete(choiceValue);
146	      next.set(itemId, {
147	        // Auto-link to this option if any choice gets checked
148	        linkedHere: cur.linkedHere || checked,
149	        choices: newChoices,
150	      });
151	      return next;
152	    });
153	  }
154	
155	  // Total computed for a particular choice (or for the option itself if checkbox)
156	  function totalFor(choiceValue: string | null): number {
157	    let total = 0;
158	    for (const it of allItems) {
159	      const d = draft.get(it.id);
160	      if (!d || !d.linkedHere) continue;
161	      if (choiceValue === null) {
162	        // Checkbox: only items with NO choice rows count toward the flat cost
163	        if (d.choices.size === 0) total += Number(it.cost);
164	      } else {
165	        if (d.choices.has(choiceValue)) total += Number(it.cost);
166	      }
167	    }
168	    return total;
169	  }
170	
171	  async function handleSave() {
172	    setSaving(true);
173	    setErrorMsg(null);
174	    try {
175	      // For each cost_item whose draft state differs from current state, send a PUT.
176	      const updates: Array<{ id: string; linked_option_id: string | null; linked_choices: string[] }> = [];
177	      for (const it of allItems) {
178	        const d = draft.get(it.id);
179	        if (!d) continue;
180	        const currentLinked = it.linked_option_id === option.id;
181	        const currentChoices = new Set(it.linked_option_id === option.id ? it.linked_choices : []);
182	        const draftChoices = d.choices;
183	        const linkedChanged = currentLinked !== d.linkedHere;
184	        const choicesChanged =
185	          currentChoices.size !== draftChoices.size ||
186	          [...draftChoices].some((c) => !currentChoices.has(c));
187	        if (!linkedChanged && !choicesChanged) continue;
188	
189	        const payload: { id: string; linked_option_id: string | null; linked_choices: string[] } = {
190	          id: it.id,
191	          linked_option_id: d.linkedHere ? option.id : null,
192	          linked_choices: [...draftChoices],
