58	export async function computeOptionCosts<T extends OptionLike>(
59	  client: Client,
60	  options: T[],
61	): Promise<T[]> {
62	  if (!options || options.length === 0) return options;
63	
64	  const optionIds = options.map((o) => o.id).filter(Boolean);
65	  if (optionIds.length === 0) return options;
66	
67	  const { data, error } = await client
68	    .from("cost_items")
69	    .select(
70	      "id, cost, linked_option_id, choices:cost_item_option_choices(choice_value)",
71	    )
72	    .in("linked_option_id", optionIds);
73	
74	  if (error) {
75	    // Don't break the API on a compute failure — fall through to stored values.
76	    console.error("[computeOptionCosts] failed to fetch linked items:", error.message);
77	    return options;
78	  }
79	
80	  const items = (data || []) as unknown as LinkedCostItem[];
81	  const itemsByOption = new Map<string, LinkedCostItem[]>();
82	  for (const item of items) {
83	    if (!item.linked_option_id) continue;
84	    if (!itemsByOption.has(item.linked_option_id)) {
85	      itemsByOption.set(item.linked_option_id, []);
86	    }
87	    itemsByOption.get(item.linked_option_id)!.push(item);
88	  }
89	
90	  // option_type='trip_cost' path: SUM(cost_items.cost) WHERE
91	  // included_in_trip_cost=true, scoped per trip_id. Bulk-fetch one sum per
92	  // distinct trip_id present in the input.
93	  const tripCostTripIds = new Set<string>();
94	  for (const opt of options) {
95	    if (opt.option_type === "trip_cost" && opt.trip_id) {
96	      tripCostTripIds.add(opt.trip_id);
97	    }
98	  }
99	  const tripCostByTripId = new Map<string, number>();
100	  if (tripCostTripIds.size > 0) {
101	    const { data: tripCostRows } = await client
102	      .from("cost_items")
103	      .select("trip_id, cost")
104	      .in("trip_id", Array.from(tripCostTripIds))
105	      .eq("included_in_trip_cost", true);
106	    for (const row of tripCostRows || []) {
107	      const tid = row.trip_id as string;
108	      tripCostByTripId.set(tid, (tripCostByTripId.get(tid) || 0) + Number(row.cost || 0));
109	    }
110	  }
111	
112	  return options.map((opt) => {
113	    if (opt.option_type === "trip_cost" && opt.trip_id) {
114	      const computed = tripCostByTripId.get(opt.trip_id) || 0;
115	      return { ...opt, cost: round2(computed) };
116	    }
117	
118	    const linked = itemsByOption.get(opt.id);
119	    if (!linked || linked.length === 0) return opt;
120	
121	    if (opt.option_type === "checkbox") {
122	      // Flat-cost items: those with no choice junction rows.
123	      const flatItems = linked.filter((i) => i.choices.length === 0);
124	      if (flatItems.length === 0) return opt;
125	      const computed = flatItems.reduce((s, i) => s + Number(i.cost), 0);
126	      return { ...opt, cost: round2(computed) };
127	    }
128	
129	    if (Array.isArray(opt.choices) && opt.choices.length > 0) {
130	      const newChoices = opt.choices.map((ch) => {
131	        const matching = linked.filter((i) =>
132	          i.choices.some((c) => c.choice_value === ch.value),
133	        );
134	        if (matching.length === 0) return ch; // no link for this choice → keep stored
135	        const computed = matching.reduce((s, i) => s + Number(i.cost), 0);
136	        return { ...ch, cost: round2(computed) };
137	      });
138	      return { ...opt, choices: newChoices };
139	    }
140	
141	    return opt;
142	  });
143	}
